SELECT n.gender, rt.role, cn.name, COUNT(*)
FROM title as t, movie_companies as mc, company_name as cn, company_type as ct, kind_type as kt, cast_info as ci, name as n, role_type as rt, movie_info as mi1, info_type as it1, person_info as pi, info_type as it2, non_leaf_1227
WHERE (t.production_year >= 1990) AND (kt.kind IN ('episode','movie','tv mini series','tv series','video game','video movie')) AND (pi.info ILIKE '%alp%') AND (rt.role IN ('actor','cinematographer','director','editor','miscellaneous crew','producer','production designer','writer')) AND it2.id = pi.info_type_id AND mc.movie_id = non_leaf_1227.t_id AND non_leaf_1227.n_id = pi.person_id AND cn.id = mc.company_id AND non_leaf_1227.ci_person_id = pi.person_id AND (it2.id IN ('39')) AND (it1.id IN ('6')) AND mc.movie_id = non_leaf_1227.ci_movie_id AND (mi1.info ILIKE '%mo%') AND ct.id = mc.company_type_id AND (t.production_year <= 2015);